pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount, uint256 interest, uint256 loanToCollateral, uint256 duration) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        vm.assume(interest > 0);
        vm.assume(loanToCollateral > 0);
        vm.assume(duration > 0);
        vm.assume(duration <= 365 days * 10);
        vm.assume(amount <= 1_000_000_000 ether);
        vm.assume(interest <= 1_000_000_000 ether);
        vm.assume(loanToCollateral <= 1_000_000_000 ether);

        // Deploy a minimal ERC20 token to be used as collateral
        MockERC20 collateralToken = new MockERC20("Collateral", "COL", 18);
        // Fund the actor with enough tokens for collateral
        uint256 collateralNeeded = (amount * (10 ** collateralToken.decimals())) / loanToCollateral;
        vm.assume(collateralNeeded > 0);
        collateralToken.mint(actor, collateralNeeded);

        // Deploy a minimal ERC20 token to be used as debt
        MockERC20 debtToken = new MockERC20("Debt", "DBT", 18);

        // Actor approves collateral transfer to C
        vm.prank(actor);
        collateralToken.approve(address(c), collateralNeeded);

        // Actor requests a loan; this will trigger safeTransferFrom of collateral to C
        vm.prank(actor);
        c.requestLoan(amount, interest, loanToCollateral, duration);

        // The collateral() function should return the address of the collateral token as stored in the immutable args
        // In the correct implementation, this is the address of the deployed collateralToken.
        // In the buggy implementation, it returns address(0x14) instead.
        assertTrue(address(c.collateral()) == address(collateralToken));
    }
}

contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            allowance[from][msg.sender] = allowed - amount;
        }
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

