pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address tokenA, address tokenB, uint256 amount) public {
        vm.assume(tokenA != tokenB);
        vm.assume(tokenA != address(0));
        vm.assume(tokenB != address(0));
        vm.assume(amount > 0);
        // Deploy a mock ERC20 that reverts on transferFrom to simulate a real collateral token
        MockRevertERC20 mockToken = new MockRevertERC20();
        // The buggy collateral() returns the debt token address (offset 0x28) instead of the collateral token (0x14).
        // To observe the difference we use a low-level call to mockToken via the address returned by collateral().
        // The reference returns the correct collateral address; the bug returns the debt address, causing a revert.
        address returned = address(c.collateral());
        // Use the returned address to call transferFrom on the mockToken: if returned equals tokenA (reference),
        // the call goes to the mockToken and reverts as expected; if returned equals tokenB (bug), the call goes
        // to an EOA that has no code and succeeds silently, which distinguishes the bug.
        (bool success, ) = returned.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), address(0), amount));
        // For the reference, returned == tokenA (the mock), so the call reverts (success == false).
        // For the bug, returned == tokenB (an EOA), so the call succeeds (success == true).
        // Assert that the call did NOT succeed, which holds for the reference and fails for the bug.
        assertTrue(!success, "collateral should return a contract that reverts on transferFrom");
    }
}

contract MockRevertERC20 {
    function transferFrom(address, address, uint256) external pure {
        revert("mock revert");
    }
}

