        uint256 loanBaseSlot = uint256(keccak256(abi.encode(loansSlot))) + loanId * 10; // each loan struct takes 10 slots (5 request + 5 loan fields) = 10 slots exactly.
        uint256 lenderSlot = loanBaseSlot + 9;
        vm.store(address(c), bytes32(lenderSlot), bytes32(uint256(uint160(lender))));
