contract InvMutTest is Test {
    C c;
    function setUp() public {
        // Deploy a minimal implementation that can be cloned by CoolerFactory
        C impl = new C();
        // Deploy the factory
        CoolerFactory factory = new CoolerFactory();
        // We need to get a Cooler instance through the factory to have proper immutable args
        // The factory creates a C implementation internally, but we can't use it directly.
        // Instead, we'll deploy a minimal setup that gives us a properly initialized C.
        // Since C is Clone and uses _getImmutableArgsOffset, we must clone it with data.
        // We'll use ClonesWithImmutableArgs directly.
        address mockCollateral = address(new ERC20Mock());
        address mockDebt = address(new ERC20Mock());
        bytes memory data = abi.encodePacked(address(this), mockCollateral, mockDebt, address(this));
        c = C(ClonesWithImmutableArgs.clone(address(impl), data));
    }

    function testFuzz_property(address lender, address approved, uint256 loanID) public {
        // Admissible: lender != address(0) and approved != address(0)
        vm.assume(lender != address(0));
        vm.assume(approved != address(0));
        // We need a loan to exist with a lender. We'll manually set up a loan via internal calls.
        // But we can only interact through public/external functions.
        // We'll use the requestLoan/clearRequest flow to create a loan.
        // However, that requires collateral/debt tokens and approvals. For simplicity, we mock the state.
        // Since C has public storage arrays, we can't set them directly.
